ALTER TABLE workforce_employees ADD COLUMN IF NOT EXISTS attendance_site_id UUID REFERENCES attendance_sites(id);
ALTER TABLE employee_face_references ADD COLUMN IF NOT EXISTS self_enrolled_at TIMESTAMPTZ;
CREATE TABLE IF NOT EXISTS aerochat_messages (
 id UUID PRIMARY KEY, employer_id UUID NOT NULL REFERENCES employer_accounts(id) ON DELETE CASCADE,
 employee_id UUID, sender_name TEXT NOT NULL, body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 2000),
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 FOREIGN KEY(employer_id,employee_id) REFERENCES workforce_employees(employer_id,id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS aerochat_company_time ON aerochat_messages(employer_id,created_at DESC);
ALTER TABLE ats_applications ADD COLUMN IF NOT EXISTS interview_room_id UUID REFERENCES meet_rooms(id);
ALTER TABLE support_agents ADD COLUMN IF NOT EXISTS is_super_admin BOOLEAN NOT NULL DEFAULT FALSE;
UPDATE support_agents SET is_super_admin=TRUE WHERE LOWER(email)='drewhlly@gmail.com';

UPDATE ats_jobs SET questions=CASE WHEN LOWER(title||' '||department) ~ 'software|engineer|developer|technology|data' THEN '[{"prompt":"A release introduces a production error. What should you do first?","options":["Delete the logs","Contain the issue and inspect monitoring","Ignore affected users","Disable all tests"],"correct":1},{"prompt":"What best prevents an SQL injection vulnerability?","options":["Longer passwords","Hiding the form","Parameterized database queries","Renaming the database"],"correct":2},{"prompt":"What should accompany a change to core business logic?","options":["Relevant automated tests and review","Only a screenshot","No documentation","A new logo"],"correct":0},{"prompt":"Two urgent tasks conflict. What should you do?","options":["Ignore both","Clarify priority and communicate a delivery plan","Hide the delay","Guess without checking"],"correct":1},{"prompt":"You discover an error in a report you submitted. What should you do?","options":["Delete the source data","Blame a colleague","Correct it and notify the responsible person","Wait until someone notices"],"correct":2},{"prompt":"How should confidential company information be handled?","options":["Through approved access-controlled channels","In a public group","On any shared device","Without checking recipients"],"correct":0}]'::jsonb WHEN LOWER(title||' '||department) ~ 'account|financ|payroll|audit' THEN '[{"prompt":"A payment does not match the invoice. What is the best next step?","options":["Approve it anyway","Delete the invoice","Reconcile supporting records before approval","Change the amount without evidence"],"correct":2},{"prompt":"Why should payment preparation and final authorization be separated?","options":["To reduce accountability","To improve control and prevent unauthorized payments","To avoid reconciliation","To remove audit trails"],"correct":1},{"prompt":"What should support an expense entry?","options":["A verbal guess","The highest estimate","No evidence","An approved source document"],"correct":3},{"prompt":"Two urgent tasks conflict. What should you do?","options":["Ignore both","Clarify priority and communicate a delivery plan","Hide the delay","Guess without checking"],"correct":1},{"prompt":"You discover an error in a report you submitted. What should you do?","options":["Delete the source data","Blame a colleague","Correct it and notify the responsible person","Wait until someone notices"],"correct":2},{"prompt":"How should confidential company information be handled?","options":["Through approved access-controlled channels","In a public group","On any shared device","Without checking recipients"],"correct":0}]'::jsonb WHEN LOWER(title||' '||department) ~ 'human resource|hr|recruit' THEN '[{"prompt":"What should guide candidate selection?","options":["Personal resemblance to the interviewer","Job-related evidence against consistent criteria","Unrelated personal characteristics","Social popularity"],"correct":1},{"prompt":"An employee reports a confidential concern. What should HR do?","options":["Share it widely","Dismiss it","Document and handle it through the confidential process","Post it publicly"],"correct":2},{"prompt":"Before changing an employee salary, what is required?","options":["An authorized approval and audit record","A colleague request only","No documentation","A public poll"],"correct":0},{"prompt":"Two urgent tasks conflict. What should you do?","options":["Ignore both","Clarify priority and communicate a delivery plan","Hide the delay","Guess without checking"],"correct":1},{"prompt":"You discover an error in a report you submitted. What should you do?","options":["Delete the source data","Blame a colleague","Correct it and notify the responsible person","Wait until someone notices"],"correct":2},{"prompt":"How should confidential company information be handled?","options":["Through approved access-controlled channels","In a public group","On any shared device","Without checking recipients"],"correct":0}]'::jsonb WHEN LOWER(title||' '||department) ~ 'sales|customer|market' THEN '[{"prompt":"A customer explains a concern. What is the best first response?","options":["Interrupt with a sales pitch","Promise an unapproved discount","Listen and clarify the need","End the conversation"],"correct":2},{"prompt":"How should a qualified sales opportunity be tracked?","options":["Only in memory","With an owner, next action and follow-up date","Without customer permission","By deleting previous notes"],"correct":1},{"prompt":"A product cannot meet a customer requirement. What should you do?","options":["Misrepresent its capabilities","Hide the limitation","Ignore the requirement","Explain honestly and offer a suitable alternative"],"correct":3},{"prompt":"Two urgent tasks conflict. What should you do?","options":["Ignore both","Clarify priority and communicate a delivery plan","Hide the delay","Guess without checking"],"correct":1},{"prompt":"You discover an error in a report you submitted. What should you do?","options":["Delete the source data","Blame a colleague","Correct it and notify the responsible person","Wait until someone notices"],"correct":2},{"prompt":"How should confidential company information be handled?","options":["Through approved access-controlled channels","In a public group","On any shared device","Without checking recipients"],"correct":0}]'::jsonb WHEN LOWER(title||' '||department) ~ 'maintenance|operation|kitchen|chef|technician|safety' THEN '[{"prompt":"Equipment presents an immediate safety hazard. What should you do first?","options":["Continue using it","Isolate the hazard and follow the escalation procedure","Wait for the monthly report","Remove the warning sign"],"correct":1},{"prompt":"What is the purpose of preventive maintenance?","options":["Replace asset records","Avoid all inspections","Reduce failures through scheduled checks","Skip safety procedures"],"correct":2},{"prompt":"What makes an incident report useful?","options":["Accurate facts, time, asset and action taken","Unverified blame","Only the repair cost","No location"],"correct":0},{"prompt":"Two urgent tasks conflict. What should you do?","options":["Ignore both","Clarify priority and communicate a delivery plan","Hide the delay","Guess without checking"],"correct":1},{"prompt":"You discover an error in a report you submitted. What should you do?","options":["Delete the source data","Blame a colleague","Correct it and notify the responsible person","Wait until someone notices"],"correct":2},{"prompt":"How should confidential company information be handled?","options":["Through approved access-controlled channels","In a public group","On any shared device","Without checking recipients"],"correct":0}]'::jsonb ELSE '[{"prompt":"Two urgent tasks conflict. What should you do?","options":["Ignore both","Clarify priority and communicate a delivery plan","Hide the delay","Guess without checking"],"correct":1},{"prompt":"You discover an error in a report you submitted. What should you do?","options":["Delete the source data","Blame a colleague","Correct it and notify the responsible person","Wait until someone notices"],"correct":2},{"prompt":"How should confidential company information be handled?","options":["Through approved access-controlled channels","In a public group","On any shared device","Without checking recipients"],"correct":0}]'::jsonb END WHERE jsonb_array_length(questions)=0;
